    41  otError Tlv::Get(const Message &aMessage, uint8_t aType, uint16_t aMaxLength, Tlv &aTlv)
    42  {
    43      otError  error = OT_ERROR_NOT_FOUND;
    44      uint16_t offset;
    45
    46      SuccessOrExit(error = GetOffset(aMessage, aType, offset));
    47      aMessage.Read(offset, sizeof(Tlv), &aTlv);
    48
    49      if (aMaxLength > sizeof(aTlv) + aTlv.GetLength())
    50      {
    51          aMaxLength = sizeof(aTlv) + aTlv.GetLength();
    52      }
    53
    54      aMessage.Read(offset, aMaxLength, &aTlv);
    55
    56  exit:
    57      return error;
    58  }
